import { ProjectState } from '../types.ts';

/**
 * Creates an EMPTY project that contains only the user's prompt.
 * The real website is generated by the AI (see BuilderWorkspace), never from a template.
 * The second message is the marker that tells the builder to start the AI build.
 */
export function createBlankProject(prompt: string, userId: string = ''): ProjectState {
  const now = new Date().toISOString();
  const stamp = Date.now();
  const id = `proj-${stamp}`;
  const clean = prompt.trim();
  return {
    id,
    _id: id,
    userId,
    name: clean.slice(0, 40) || 'New project',
    description: clean,
    version: 1,
    status: 'building',
    createdAt: now,
    updatedAt: now,
    files: {},
    messages: [
      { id: `${stamp}-user`, role: 'user', content: clean, timestamp: now },
      { id: `${stamp}-ai`, role: 'assistant', content: 'Planning project structure...', timestamp: now }
    ],
    databaseTables: [],
    changeHistory: []
  };
}
